    if type(plan['workers'])is not int or not 1<=plan['workers']<=4:raise ValueError('invalid workers')
    if not isinstance(plan['ttls'],dict)or set(plan['ttls'])!=set(requests)or any(type(v)is not int or not 10000<=v<=120000 for v in plan['ttls'].values()):raise ValueError('invalid TTL plan')
    if len(plan['ttls'])>1 and len(set(plan['ttls'].values()))<2:raise ValueError('multi-key plan must stagger TTL budgets')
    if type(plan['negative_ttl_ms'])is not int or not 1000<=plan['negative_ttl_ms']<=10000:raise ValueError('invalid negative TTL')

