"""Provided private single-writer immutable phase files; root aliases resolve normally."""
import json,os,pathlib,secrets

def load(path):
    if path.is_symlink()or not path.is_file():raise ValueError('phase file missing or symlink')
    return json.loads(path.read_text(encoding='utf-8'))

def directory(root,generation):
    root=pathlib.Path(root);root.mkdir(parents=True,exist_ok=True);root=root.resolve();path=root/generation
    if path.is_symlink():raise ValueError('generation symlink refused')
    path.mkdir(exist_ok=True)
    if path.resolve().parent!=root:raise ValueError('generation escaped root')
    return path

def publish(path,value):
    if path.is_symlink():raise ValueError('phase symlink refused')
    encoded=(json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(',',':'))+'\n').encode()
    if path.exists():
        if path.read_bytes()!=encoded:raise ValueError('immutable phase differs')
        return
    temporary=path.parent/('.phase-'+secrets.token_hex(8))
    try:
        with temporary.open('xb')as handle:handle.write(encoded);handle.flush();os.fsync(handle.fileno())
        try:os.link(temporary,path)
        except FileExistsError:
            if path.is_symlink()or path.read_bytes()!=encoded:raise ValueError('immutable phase differs')
    finally:temporary.unlink(missing_ok=True)

